using System.ComponentModel;
using System.Net.Http.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class FetchDataTool
{
    [McpServerTool, Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        ILogger<FetchDataTool> logger,
        [Description("The API path to fetch (e.g. \"/users/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("ExternalApi");

        logger.LogInformation("Fetching data from {Path}", path);

        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);

        logger.LogInformation("Received {Length} characters", content.Length);

        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the given text.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Optional desired length: short, medium, or detailed.")] string style = "medium")
    {
        var systemMessage = style switch
        {
            "short" => "Summarize the following text in 1-2 sentences.",
            "detailed" => "Provide a comprehensive summary covering all key points.",
            _ => "Summarize the following text in a concise paragraph."
        };

        return
        [
            new McpServerPromptMessage
            {
                Role = Role.User,
                Content = new Content { Text = $"{systemMessage}\n\n{text}" }
            }
        ];
    }
}

